sys_variable_value.value:
(function execute(inputs, outputs) {
    var totalSpend = 0;
    
    if (inputs.hardware_records) {
        var gr = inputs.hardware_records;
        
        // Iterate through all records returned by Look Up Records
        while (gr.next()) {
            // Get raw cost string and sanitize currency formatting
            var rawCost = String(gr.getValue('cost') || gr.cost || '').replace(/[^0-9.]/g, '');
            var cost = parseFloat(rawCost) || 0;
            totalSpend += cost;
        }
    }
    
    // Get factor rate
    var rawFactor = String(inputs.factor_rate || inputs.factor || '0.42').replace(/[^0-9.]/g, '');
    var factor = parseFloat(rawFactor) || 0;
    
    // Calculate final CO2e
    var totalCo2e = totalSpend * factor;
    outputs.total_co2e_lbs = totalCo2e.toFixed(2);
})(inputs, outputs);

